<script lang="ts">
 import {goto} from '$app/navigation';import type {Claim,Line,Status as ClaimStatus} from '../types';import {categories} from '../types';import {claimStore} from '../store';import {app,refresh,run,notify,usage} from '../app.svelte';import {money,total,lineAmount,decimal,inputMoney} from '../money';import {newLine,todayLocal} from '../sample';import Icon from '../components/Icon.svelte';import Status from '../components/Status.svelte';import Findings from '../components/Findings.svelte';import Modal from '../components/Modal.svelte';import ReceiptThumb from '../components/ReceiptThumb.svelte';import {claimPDF,download} from '../exports';
 export let initial:Claim;let c:Claim=JSON.parse(JSON.stringify(initial));let selected=c.lines[0]?.id||'';let comment='',confirmDelete=false,receiptUrl='',receiptName='',zoom=100,busy=false,action:ClaimStatus|null=null;
 $: actor=app.data!.users.find(u=>u.id===app.data!.session?.userId)!;$: editable=actor.role==='Employee'&&c.ownerId===actor.id&&['Draft','Returned for correction'].includes(c.status);$: policy=claimStore.policyFor(c);$: findings=claimStore.findings(c);$: blocks=findings.filter(f=>f.severity==='Block').length;$: warnings=findings.filter(f=>f.severity==='Warn').length;$: line=c.lines.find(l=>l.id===selected);$: history=app.data!.audit.filter(a=>a.claimId===c.id);
 function reload(){const saved=claimStore.view().claims.find(x=>x.id===c.id);if(saved)c=saved;refresh();}
 function number(l:Line,key:'amount'|'tax'|'quantity'|'rate'|'foreignAmount'|'fxRate',value:string){try{if(key==='tax'&&!value){l.tax=undefined;}else l[key]=decimal(value,key==='fxRate'?6:key==='quantity'?(l.kind==='mileage'?3:0):2);c={...c,lines:[...c.lines]};}catch(e){notify((e as Error).message);}}
 function kindChanged(l:Line){l.rate=l.kind==='perdiem'?policy.perDiem:policy.mileageRate;l.quantity=l.kind==='perdiem'?1:0;l.currency='INR';c={...c};}
 async function save(){await run(()=>claimStore.saveDraft(c),'Draft saved in this browser.');}
 async function submit(){await run(()=>{claimStore.saveDraft(c);claimStore.change(c.id,'Submitted','Submitted for review.');reload();},'Claim submitted. Your manager has an in-app notification.');}
 async function decide(next:ClaimStatus){await run(()=>{claimStore.change(c.id,next,comment);reload();action=null;comment='';},next==='Manager approved'?'Approval recorded.':'Claim updated.');}
 async function lineDecision(l:Line,decision:'approved'|'rejected'){await run(()=>{claimStore.lineDecision(c.id,l.id,decision,comment);reload();},'Line decision recorded. Approved total recalculated.');}
 async function attach(event:Event,l:Line){const input=event.target as HTMLInputElement;busy=true;try{for(const file of Array.from(input.files||[])){if(l.receipts.length>=10)throw new Error('Use at most 10 images per expense.');const ref=await claimStore.addReceipt(file);l.receipts=[...l.receipts,ref];}c={...c};claimStore.saveDraft(c);refresh();usage();notify('Receipt compressed below 200 KB and stored in this browser.');}catch(e){notify((e as Error).message);}finally{busy=false;input.value='';}}
 async function openReceipt(id:string,name:string){await run(async()=>{const blob=await claimStore.receipt(id);if(!blob)throw new Error('This receipt is missing from browser storage.');receiptUrl=URL.createObjectURL(blob);receiptName=name;zoom=100;});}
 function closeReceipt(){URL.revokeObjectURL(receiptUrl);receiptUrl='';}
 async function pdf(){busy=true;await run(async()=>{const bytes=await claimPDF(c,app.data!,policy,findings,id=>claimStore.receipt(id));download(new Blob([new Uint8Array(bytes)],{type:'application/pdf'}),c.number+'.pdf');},'PDF generated entirely in your browser.');busy=false;}
 async function duplicate(){const copy=await run(()=>claimStore.create(c.id));if(copy)goto('/claims/'+copy.id);}
</script>
<div class="detail-breadcrumb"><a href={actor.role==='Employee'?'/claims':actor.role==='Manager'?'/manager':'/finance'}>All claims</a><Icon name="chevron" size={14}/><span>{c.number}</span></div>
<div class="page-header"><div><div class="heading-inline"><h1>{editable?(c.status==='Draft'?'Claim workspace':'Correct your claim'):c.title}</h1><Status status={c.status}/></div><p>{c.number} <span class="separator">·</span> {app.data!.users.find(u=>u.id===c.ownerId)?.name} <span class="separator">·</span> {c.department}</p></div><div class="button-group">{#if actor.role==='Employee'}<button onclick={duplicate}><Icon name="copy" size={16}/>Duplicate</button>{/if}<button onclick={pdf} disabled={busy}><Icon name="download" size={16}/>Claim PDF</button></div></div>
{#if c.status==='Returned for correction'}<div class="notice warning-notice"><Icon name="return"/><div><strong>Returned for correction</strong><p>{[...history].reverse().find(a=>a.status==='Returned for correction')?.comment} · Edit the details and resubmit. Earlier history stays intact.</p></div></div>{/if}
<div class="claim-layout"><div class="claim-main"><section class="panel form-panel"><div class="panel-heading"><div><h2>Claim details</h2><p>A clear purpose makes a faster review.</p></div><span class="step-label">01</span></div>{#if editable}<div class="form-grid"><label class="span-2">Title / business purpose<input bind:value={c.title} maxlength="160" placeholder="e.g. Client workshop in Bengaluru"/></label><label>Project / cost centre<input bind:value={c.costCentre} maxlength="60" placeholder="e.g. ENG-101"/></label><label>Reimbursement currency<input value="INR — Indian rupee" disabled/></label><label>Trip start <span class="optional">optional</span><input type="date" bind:value={c.tripStart}/></label><label>Trip end <span class="optional">optional</span><input type="date" bind:value={c.tripEnd}/></label></div>{:else}<dl class="detail-grid"><div><dt>Business purpose</dt><dd>{c.title}</dd></div><div><dt>Cost centre</dt><dd>{c.costCentre}</dd></div><div><dt>Trip period</dt><dd>{c.tripStart?c.tripStart+' to '+c.tripEnd:'No trip dates'}</dd></div><div><dt>Policy version</dt><dd>Version {c.policyVersion||policy.version}</dd></div></dl>{/if}</section>
<section class="panel line-panel"><div class="panel-heading"><div><h2>Expense lines <span class="count">{c.lines.length}</span></h2><p>Amounts are tax-inclusive. Foreign rates are entered manually.</p></div><span class="step-label">02</span></div><div class="expense-lines">{#each c.lines as l,i}<button class="expense-row" class:selected={selected===l.id} onclick={()=>selected=l.id}><span class="line-number">{String(i+1).padStart(2,'0')}</span><span><strong>{l.vendor||'New expense'}</strong><small>{l.category} · {l.date||'Date required'}</small></span><span class="line-amount">{money(lineAmount(l))}<small>{l.decision||l.kind}</small></span><span class="line-signal">{#if findings.some(f=>f.lineId===l.id&&f.severity==='Block')}<Status status="Block"/>{:else if findings.some(f=>f.lineId===l.id&&f.severity==='Warn')}<Status status="Warn"/>{:else}<Icon name="check" size={16}/>{/if}</span></button>{/each}</div>
{#if line}<div class="line-editor"><div class="line-editor-title"><h3>Expense {c.lines.indexOf(line)+1}</h3>{#if editable&&c.lines.length>1}<button class="text-button danger-text" onclick={()=>{c.lines=c.lines.filter(l=>l.id!==selected);selected=c.lines[0].id;}}><Icon name="trash" size={15}/>Remove line</button>{/if}</div>{#if editable}<div class="form-grid"><label>Expense type<select bind:value={line.kind} onchange={()=>kindChanged(line)}><option value="expense">Standard expense</option><option value="mileage">Mileage</option><option value="perdiem">Per diem</option></select></label><label>Expense date<input type="date" bind:value={line.date}/></label><label>Category<select bind:value={line.category}>{#each categories as category}<option>{category}</option>{/each}</select></label><label>Vendor / payee<input bind:value={line.vendor} maxlength="120" placeholder="Name on the receipt"/></label><label class="span-2">Description<input bind:value={line.description} maxlength="300" placeholder="What was this expense for?"/></label>
{#if line.kind!=='expense'}<label>{line.kind==='mileage'?'Distance (km)':'Travel days'}<input type="number" min="0" step={line.kind==='mileage'?'.001':'1'} value={line.kind==='mileage'?line.quantity/1000:line.quantity} onchange={(e)=>number(line!,'quantity',e.currentTarget.value)}/></label><label>{line.kind==='mileage'?'Rate per km (INR)':'Policy rate per day (INR)'}<input type="number" min="0" step=".01" value={inputMoney(line.rate)} readonly={line.kind==='perdiem'} onchange={(e)=>number(line!,'rate',e.currentTarget.value)}/></label><div class="calculation span-2">{line.kind==='mileage'?line.quantity/1000:line.quantity} {line.kind==='mileage'?'km':'days'} × {money(line.rate)} = <strong>{money(lineAmount(line))}</strong></div>{:else}<label>Currency<select bind:value={line.currency}><option>INR</option><option>USD</option><option>EUR</option><option>GBP</option></select></label><label>Amount ({line.currency})<input type="number" min="0" step=".01" value={inputMoney(line.currency==='INR'?line.amount:line.foreignAmount)} onchange={(e)=>number(line!,line!.currency==='INR'?'amount':'foreignAmount',e.currentTarget.value)}/></label>{#if line.currency!=='INR'}<label>Exchange rate (INR per {line.currency})<input type="number" min="0" step=".000001" value={line.fxRate/1000000} onchange={(e)=>number(line!,'fxRate',e.currentTarget.value)}/></label><div class="calculation">INR amount <strong>{money(lineAmount(line))}</strong><small>Rate entered manually</small></div>{/if}<label>Included tax (INR) <span class="optional">optional</span><input type="number" min="0" step=".01" value={line.tax===undefined?'':inputMoney(line.tax)} onchange={(e)=>number(line!,'tax',e.currentTarget.value)}/></label>{/if}<label>Paid with<select bind:value={line.payment}><option value="personal card">Personal card</option><option value="cash">Cash</option><option value="UPI">UPI</option></select></label>{#if line.category==='Client entertainment'}<label class="span-2">Attendee names<input bind:value={line.attendees} placeholder="Separate each name with a comma"/></label>{/if}<label class="span-2">Notes <span class="optional">optional</span><textarea bind:value={line.notes} rows="2" maxlength="1000"></textarea></label></div>{:else}<dl class="detail-grid"><div><dt>Vendor</dt><dd>{line.vendor}</dd></div><div><dt>Category / date</dt><dd>{line.category} · {line.date}</dd></div><div><dt>Description</dt><dd>{line.description}</dd></div><div><dt>Amount / included tax</dt><dd>{money(lineAmount(line))} / {line.tax===undefined?'Not provided':money(line.tax)}</dd></div><div><dt>Payment method</dt><dd>{line.payment}</dd></div><div><dt>Attendees / notes</dt><dd>{line.attendees||line.notes||'None'}</dd></div></dl>{/if}
<div class="receipt-section"><div><h3>Receipts</h3><p>Private, compressed images. Stored in this browser only.</p></div><div class="receipts-grid">{#each line.receipts as r}<div><ReceiptThumb id={r.id} name={r.name} onclick={()=>openReceipt(r.id,r.name)}/>{#if editable}<button class="text-button" aria-label={'Remove receipt '+r.name} onclick={()=>{line!.receipts=line!.receipts.filter(x=>x.id!==r.id);c={...c};}}>Remove</button>{/if}</div>{/each}{#if editable}<label class="receipt-upload"><Icon name="upload" size={24}/><strong>{busy?'Processing…':'Add receipt'}</strong><span>JPEG, PNG or WebP · up to 20 MB</span><input type="file" accept="image/jpeg,image/png,image/webp" multiple aria-label="Upload receipt images" disabled={busy} onchange={(e)=>attach(e,line!)}/></label><label class="button camera-label"><Icon name="receipt" size={16}/>Take photo<input type="file" accept="image/*" capture="environment" aria-label="Take a receipt photo" onchange={(e)=>attach(e,line!)}/></label>{/if}</div></div><Findings findings={findings.filter(f=>f.lineId===line?.id)} compact/>
{#if actor.role==='Manager'&&c.status==='Submitted'&&!c.managerApprovals.length}<div class="line-decisions"><span>Line decision: <strong>{line.decision||'Pending (included in approval)'}</strong></span><button onclick={()=>lineDecision(line!,'approved')}>Approve line</button><button class="danger-text" onclick={()=>lineDecision(line!,'rejected')}>Reject line</button></div>{/if}</div>{/if}
{#if editable}<div class="add-line"><button onclick={()=>{const l=newLine(todayLocal(),policy.mileageRate);c.lines=[...c.lines,l];selected=l.id;}}><Icon name="plus" size={16}/>Add expense line</button></div>{/if}</section>
{#if editable||c.justification}<section class="panel form-panel"><div class="panel-heading"><div><h2>Policy justification</h2><p>Required when any warning is present. Blocks cannot be overridden.</p></div><Icon name="shield"/></div>{#if editable}<label>Explain the business reason for all warnings<textarea bind:value={c.justification} rows="3" maxlength="2000" placeholder="Explain why this expense is appropriate despite the warning."></textarea></label>{:else}<p>{c.justification}</p>{/if}</section>{/if}
<section class="panel"><div class="panel-heading"><div><h2>Activity & approval trail</h2><p>Append-only history. Earlier entries cannot be changed in the app.</p></div><Icon name="clock"/></div><ol class="timeline">{#each history as event}<li><span class="timeline-dot"></span><div><strong>{event.status}</strong><p>{event.comment}</p><small>{event.actorName} · {event.role} · {new Date(event.time).toLocaleString('en-IN')}</small></div></li>{/each}</ol></section></div>
<aside class="claim-sidebar"><section class="panel policy-summary"><div class="panel-heading"><h2>Policy check</h2><Icon name="shield"/></div><div class="policy-score"><div><strong class:danger-text={blocks>0}>{blocks}</strong><span>Blocks</span></div><div><strong class:text-warning={warnings>0}>{warnings}</strong><span>Warnings</span></div><div><strong>{findings.filter(f=>f.severity==='Info').length}</strong><span>Info</span></div></div><p>{blocks?'Resolve every block before submission.':warnings?'Add a justification to submit with warnings.':'Your claim is clear of policy findings.'}</p><div class="policy-version"><Icon name="lock" size={15}/><span>Policy v{c.policyVersion||policy.version}<small>{c.policyVersion?'Fixed for this claim':'Locked on first submission'}</small></span></div>{#if findings.some(f=>!f.lineId)}<Findings findings={findings.filter(f=>!f.lineId)} compact/>{/if}</section>
<section class="panel totals-panel"><h2>Claim summary</h2><div><span>Requested amount</span><strong>{money(total(c.lines))}</strong></div><div><span>Rejected lines</span><strong>{money(total(c.lines.filter(l=>l.decision==='rejected')))}</strong></div><div class="approved-total"><span>Approved amount</span><strong>{money(total(c.lines,true))}</strong></div><small>{['Draft','Submitted','Returned for correction'].includes(c.status)?'Provisional until the manager completes approval.':'Excludes individually rejected expense lines.'}</small></section>
{#if (actor.role==='Manager'&&c.status==='Submitted')||(actor.role==='Finance'&&c.status==='Manager approved')}<section class="panel review-panel"><h2>{actor.role==='Manager'?'Manager review':'Finance review'}</h2>{#if c.managerApprovals.length&&c.status==='Submitted'}<p>First-level approval recorded. A different assigned manager must approve.</p>{/if}<label>Review comment<textarea bind:value={comment} rows="3" placeholder="Required for rejection or return, including line rejection."></textarea></label><button class="primary full" onclick={()=>decide(actor.role==='Manager'?'Manager approved':'Finance approved')}>{actor.role==='Manager'?'Approve claim':'Approve for payment'}</button><div class="button-group"><button onclick={()=>action='Returned for correction'}>Return</button><button class="danger-text" onclick={()=>action='Rejected'}>Reject</button></div></section>{/if}
{#if actor.role==='Employee'&&['Submitted','Returned for correction'].includes(c.status)}<button class="full" onclick={()=>action='Cancelled'}>Cancel claim</button>{/if}{#if editable&&c.status==='Draft'}<button class="full danger-text" onclick={()=>confirmDelete=true}><Icon name="trash" size={16}/>Delete draft</button>{/if}</aside></div>
{#if editable}<div class="sticky-totals"><div><span>Total requested</span><strong>{money(total(c.lines))}</strong><small>{c.lines.length} expenses · {blocks} blocks · {warnings} warnings</small></div><div class="button-group"><button onclick={save} disabled={busy}>Save draft</button><button class="primary" onclick={submit} disabled={busy||blocks>0}>Submit claim<Icon name="arrow" size={17}/></button></div></div>{/if}
{#if confirmDelete}<Modal title="Delete this draft?" onclose={()=>confirmDelete=false}><p>The draft will be removed. Its claim number will never be reused, and its audit entries remain in the browser backup.</p><div class="modal-actions"><button onclick={()=>confirmDelete=false}>Keep draft</button><button class="danger-button" onclick={async()=>{const result=await run(()=>{claimStore.deleteDraft(c.id);return true;},'Draft deleted.');if(result)goto('/claims');}}>Delete draft</button></div></Modal>{/if}
{#if action}<Modal title={action==='Cancelled'?'Cancel this claim?':action==='Rejected'?'Reject this claim?':'Return for correction?'} onclose={()=>action=null}><label>Required comment<textarea bind:value={comment} rows="3"></textarea></label><div class="modal-actions"><button onclick={()=>action=null}>Go back</button><button class={action==='Rejected'?'danger-button':'primary'} disabled={!comment.trim()} onclick={()=>decide(action!)}>Confirm decision</button></div></Modal>{/if}
{#if receiptUrl}<Modal title={'Receipt · '+receiptName} onclose={closeReceipt}><div class="receipt-toolbar"><label>Zoom<input type="range" min="50" max="250" step="25" bind:value={zoom}/></label><span>{zoom}%</span></div><div class="receipt-viewer"><img src={receiptUrl} alt={'Receipt: '+receiptName} style={`width:${zoom}%;max-width:none`}/></div><p class="field-help">This image is loaded from IndexedDB, not from a server.</p></Modal>{/if}